mapper.update:
update con_contract_cashflow
set cf_status = #{cfStatus}
WHERE CONTRACT_ID = #{contractId}
  AND DUE_DATE >= #{dueDate}

mapper.select:
select ccc.cashflow_id, nvl(ccc.due_amount,0) - nvl(ccc.billing_amount,0) un_open_amount, nvl(ccc.billing_amount,0)billing_amount, nvl(ccc.billing_principal,0)billing_principal, nvl(ccc.billing_interest,0)billing_interest, nvl(ccc.due_amount,0)due_amount, nvl(ccc.principal,0)principal, nvl(ccc.interest,0)interest,ccc.times from con_contract_cashflow ccc where ccc.cashflow_id in
#{cashflowId}
order by times asc

SELECT t.* from ( SELECT cc.BUSINESS_TYPE, ccc.cashflow_id, cc.contract_id, cc.contract_number, cc.legal_contract_number, cc.contract_name, pp.contract_number as prj_con_number, ccc. TIMES, ccc.cf_item, ccc.cf_type, ccc.due_date, (case when cc.business_type = 'LEASE' and ccc.cf_item = 1 then ccc.due_amount when cc.business_type = 'LEASEBACK' and ccc.cf_item = 1 then ccc.interest when ccc.cf_item in (3, 8) then ccc.due_amount else 0 end) as due_amount, (case when cc.business_type = 'LEASE' and ccc.cf_item = 1 then ccc.due_amount - nvl(ccc.billing_amount, 0) when cc.business_type = 'LEASEBACK' and ccc.cf_item = 1 then ccc.interest - nvl(ccc.billing_amount, 0) when ccc.cf_item in (3, 8) then ccc.due_amount - nvl(ccc.billing_amount, 0) else 0 end) as not_billing_amount, (SELECT sc.meaning FROM sc WHERE sc.code_value = ccc.write_off_flag AND sc. CODE = 'CON.CASHFLOW_WRITE_OFF_FLAG') as write_off_flag_desc, ccc.write_off_flag, ccc.billing_amount, (nvl(ccc.billing_amount, 0) - (nvl(ccc.billing_amount, 0) * cc.vat_rate)) net_amount, (nvl(ccc.billing_amount, 0) * cc.vat_rate) vat_amount, ccc.cf_direction, ccc.billing_status, (select sc.meaning from sys_code_value_b_v sc where sc.code = 'HLS.BILLING_STATUS' and ccc.billing_status = sc.code_value and sc.enabled_flag='Y') billing_status_n, cc.contract_status, (case when cc.business_type = 'LEASE' and ccc.cf_item = 1 then '租金' when cc.business_type = 'LEASEBACK' and ccc.cf_item = 1 then '利息' else hci.description end) as cf_Item_Desc, (SELECT hds.DESCRIPTION FROM hls_document_status hds WHERE hds.document_category = 'CON_CONTRACT' AND hds.status_code = nvl(cc.contract_status, 'NEW')) AS contract_status_desc, cba.bp_tax_registry_num AS tax_registry_num, cba.bp_tax_registry_num AS bp_tax_registry_num, cba.bp_address_phone_num AS invoice_bp_address_phone_num, cba.bp_address_phone_num AS bp_address_phone_num, cba.bp_bank_account AS invoice_bp_bank_account, cba.bp_bank_account AS bp_bank_account, hbm.bp_id, hbm.bp_name invoice_title, fttc.tax_type_rate, (SELECT SCVB.MEANING FROM SYS_CODE_B scb, SYS_CODE_VALUE_B scvb WHERE fttc.tax_type_code = vipd.tax_type_code AND fttc.company_id = cc.company_id AND scb.CODE_ID = SCVB.CODE_ID AND SCB.CODE = 'VAT.INVOICE_KIND' AND SCVB. VALUE = vipd.INVOICE_KIND) AS invoice_kind_desc, vipd.invoice_kind, cc.company_id, pp.host_project_manager, (SELECT s.description FROM sys_user s WHERE s.user_id = pp.host_project_manager) AS employee_name, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = cc.unit_id) as unit_name FROM con_contract_cashflow ccc, con_contract cc, prj_project pp, con_contract_bank_account cba, vat_invoice_profile_dtl vipd, hls_cashflow_item hci, hls_bp_master hbm, fnd_tax_type_code fttc WHERE ccc.cf_direction = 'INFLOW' and cba.contract_id = cc.contract_id and ccc.billing_status IN ('NOT', 'PARTIAL') AND hci.cf_type = ccc.cf_type AND hci.cf_item = ccc.cf_item AND hbm.bp_id = cc.tenant_id and cc.contract_id = ccc.contract_id AND cc.project_id = pp.project_id AND fttc.tax_type_code = vipd.tax_type_code AND fttc.company_id = cc.company_id AND ccc.cf_item = (CASE WHEN vipd.cf_item = 101 THEN 1 ELSE vipd.cf_item END) AND vipd.enabled_flag = 'Y' AND cc.data_class = 'NORMAL' and (pp.HOST_PROJECT_MANAGER = #{request.userId} or #{request.employeeCode} IS NULL or #{request.employeeCode} ='ADMIN') and ccc.cf_item in (1, 3, 8) and (case when (cc.business_type = 'LEASE' and cc.lease_item_property = 'MOVABLE') THEN 'LEASE_MOVABLES' when (cc.business_type = 'LEASE' and cc.lease_item_property = 'IMMOVABLE') THEN 'LEASE_IMMOVABLES' when (cc.business_type = 'LEASEBACK' and cc.lease_item_property = 'MOVABLE') THEN 'LEASEBACK_MOVABLES' when (cc.business_type = 'LEASEBACK' and cc.lease_item_property = 'IMMOVABLE') THEN 'LEASEBACK_IMMOVABLES' else '' end) = vipd.invoice_profile
) t where t.due_amount > t.billing_amount
AND t.times >= #{timesFrom}
AND t.times <= #{timesTo}
and t.due_date >= #{dueDateFrom}
and t.due_date <= #{dueDateTo}
AND to_days(#{dueDate}) >= to_days(t.due_date)
AND t.contract_name LIKE concat('%',concat(#{contractName},'%') )
AND t.contract_number LIKE concat('%',concat(#{contractNumber},'%') )
AND t.prj_con_number LIKE concat('%',concat(#{prjConNumber},'%') )
AND t.cf_Item_Desc=#{cfItemDesc}
AND t.cf_item = #{cfItem}
AND t.contract_status_desc = #{contractStatusDesc}
AND t.write_off_flag_desc = #{writeOffFlagDesc}
AND t.write_off_flag = #{writeOffFlag}
AND t.invoice_kind_desc = #{invoiceKindDesc}
AND t.legal_contract_number LIKE concat('%',concat(#{legalContractNumber},'%') )
ORDER BY t.contract_number, t.times

select t.* from (SELECT cc.contract_id, c.project_id, c.contract_number, pp.approval_number, c.document_category, (select hdc.description from HLS_DOCUMENT_CATEGORY hdc where hdc.document_category = c.document_category) as document_category_desc, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id=c.return_account ) as back_bank_account_num, cc.times, cc.due_date, --cast(cc.due_date as char) as due_date_desc, cc.due_date as due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) as due_amount_format, cc.cf_item, cc.cf_type, cc.cashflow_id, (select ci.description from hls_cashflow_item ci where ci.cf_item = cc.cf_item and ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format, FORMAT(nvl(cc.received_amount,0),2) received_amount_format, nvl(cc.received_amount,0) received_amount, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=c.tenant_id) bp_name, case cc.write_off_flag when'NOT' then '未核销' when 'PARTIAL' then '部分核销' when 'FULL' then '完全核销' end as write_off_flag_desc, c.company_id FROM con_contract_cashflow cc, con_contract c, prj_project pp where cc.cf_direction ='INFLOW' and c.project_id=pp.project_id and nvl(cc.write_off_flag,'NOT') !='FULL' and c.contract_id = cc.contract_id and ((c.contract_status in('INCEPT')) or (cc.times<=0 and c.contract_status in('SIGN','LOAN'))) and c.write_off_able_flag='Y' and c.data_class = 'NORMAL' and cc.cf_status = 'RELEASE' and ((cc.cf_item=14 and cc.generated_source='CSH_DEPOSIT_DEDUCTION' and cc.generated_source_doc_id in (select d.deposit_deduction_id from csh_deposit_deduction d, csh_deposit_deduction_hd h where d.deposit_deduction_hd_id=h.deposit_deduction_hd_id and h.deposit_status='BACK_APPROVED') ) or (cc.cf_item!=14)) UNION SELECT cc.contract_id, c.project_id, c.contract_number, c.approval_number, c.document_category, (select hdc.description from HLS_DOCUMENT_CATEGORY hdc where hdc.document_category = c.document_category) as document_category_desc, (select cba.bank_account_num from csh_bank_account cba where cba.bank_account_id=c.fct_payment_account_id ) as back_bank_account_num, cc.times, cc.due_date, --cast(cc.due_date as char) as due_date_desc, cc.due_date as due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) as due_amount_format, cc.cf_item, cc.cf_type, cc.quotation_cashflow_id as cashflow_id, (select ci.description from hls_cashflow_item ci where ci.cf_item = cc.cf_item and ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format, FORMAT(nvl(cc.received_amount,0),2) received_amount_format, nvl(cc.received_amount,0) received_amount, case when cc.cf_item=54 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.principal_repayment_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) when cc.cf_item=51 then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.repay_guarantee_party='Y' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( case fp.fund_restream_method when 'DIRECT' then ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='SELLER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) else ( select max(hbm.bp_name) from fct_project_bp fpb , hls_bp_master hbm where fpb.bp_role_type='BUYER' and hbm.bp_id=fpb.bp_id and fpb.project_id=fp.project_id) end) end bp_name,
case cc.write_off_flag when'NOT' then '未核销' when 'PARTIAL' then '部分核销' when 'FULL' then '完全核销' end as write_off_flag_desc, c.company_id FROM fct_quotation_cashflow cc, fct_contract c, fct_project fp where cc.cf_direction ='INFLOW' and nvl(cc.write_off_flag,'NOT') !='FULL' and c.contract_id = cc.contract_id and fp.project_id=c.project_id and ((c.contract_status in('INCEPT')) or (cc.times=0 and c.contract_status in('SIGN','LOAN'))) and c.data_class = 'NORMAL' and cc.cf_status = 'RELEASE' and ((cc.cf_item=14 and cc.generated_source='CSH_DEPOSIT_DEDUCTION' and cc.generated_source_doc_id in (select d.deposit_deduction_id from csh_deposit_deduction d, csh_deposit_deduction_hd h where d.deposit_deduction_hd_id=h.deposit_deduction_hd_id and h.deposit_status='BACK_APPROVED') ) or (cc.cf_item!=14)) ) t
1=1 AND T.CASHFLOW_ID NOT IN ( SELECT CWOM.CASHFLOW_ID FROM CSH_WRITE_OFF_MATCH CWOM WHERE CWOM.WRITE_FLAG IN('R', 'N') AND CWOM.CASHFLOW_ID IS NOT NULL ) AND t.company_id=#{request.companyId}
and t.cf_item = #{cfItemFlag}
and t.contract_number LIKE concat('%',concat(#{contractNumber},'%') )
and t.approval_number LIKE concat('%',concat(#{approvalNumber},'%') )
and t.times = #{times}
AND t.bp_name LIKE concat('%',concat(#{bpName},'%') )
AND t.due_date =#{dueDate}
AND t.due_date >=#{dueDateFrom}
AND t.due_date <=#{dueDateTo}
and t.bpId = #{bpId}
and t.cf_item_desc = #{cfItemDesc}

SELECT t.*, CASE WHEN t.write_off_flag='NOT' THEN '未核销' WHEN t.write_off_flag='PARTIAL' THEN '部分核销' WHEN t.write_off_flag='FULL' THEN '完全核销' END AS write_off_flag_desc FROM ( SELECT cc.contract_id, c.unit_id, c.project_id, c.contract_number, c.contract_name, pp.approval_number, c.document_category, ( select fp.APPROVAL_NUMBER from fct_project fp where fp.project_id = c.PROJECT_ID ) as contract_content_number, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, cc.times, cc.due_date, cc.due_date AS due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) AS due_amount_format, cc.cf_item, cc.cf_type, cc.cashflow_id, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = cc.cf_item AND ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format, FORMAT(nvl(cc.received_amount,0),2) received_amount_format, nvl(cc.received_amount,0) received_amount, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id=c.tenant_id) bp_name, ( SELECT hbm.bp_code FROM hls_bp_master hbm WHERE hbm.bp_id=c.tenant_id) bp_code, c.currency, ( SELECT currency_name FROM fnd_currency fc WHERE fc.currency_code = c.currency ) currency_name, cc.write_off_flag, c.COMPANY_ID, a.bank_account_name back_bank_account_name, a.bank_account_num back_bank_account_num, cb.bank_name back_bank_name FROM con_contract_cashflow cc join con_contract c on c.contract_id = cc.contract_id join prj_project pp on pp.project_id=c.project_id LEFT JOIN csh_bank_account a ON c.return_account=a.bank_account_id LEFT JOIN csh_bank cb on cb.bank_id=a.bank_id WHERE cc.cf_direction ='INFLOW' AND nvl(cc.write_off_flag,'NOT') !='FULL' and ((c.contract_status in('INCEPT')) or (cc.times=0 and c.contract_status in('SIGN'))) AND c.write_off_able_flag='Y' AND c.data_class = 'NORMAL' AND cc.cf_status = 'RELEASE' UNION SELECT cc.contract_id, c.unit_id, c.project_id, c.contract_number, c.contract_name, c.approval_number, c.document_category, ( select fp.APPROVAL_NUMBER from fct_project fp where fp.project_id = c.PROJECT_ID ) as contract_content_number, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, cc.times, cc.due_date, --cast(cc.due_date as char) as due_date_desc, cc.due_date AS due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) AS due_amount_format, cc.cf_item, cc.cf_type, cc.quotation_cashflow_id AS cashflow_id, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = cc.cf_item AND ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format, FORMAT(nvl(cc.received_amount,0),2) received_amount_format, nvl(cc.received_amount,0) received_amount, ( SELECT MAX(hbm.bp_name) FROM fct_project_bp fpb , hls_bp_master hbm WHERE fpb.project_id=c.project_id AND fpb.bp_id=hbm.bp_id AND fpb.CREDIT_GRANTOR_PARTY='Y') bp_name, ( SELECT MAX(hbm.bp_code) FROM fct_project_bp fpb , hls_bp_master hbm WHERE fpb.project_id=c.project_id AND fpb.bp_id=hbm.bp_id AND fpb.CREDIT_GRANTOR_PARTY='Y') bp_code, c.currency, ( SELECT currency_name FROM fnd_currency fc WHERE fc.currency_code = c.currency ) currency_name, cc.write_off_flag, c.company_id, a.bank_account_name back_bank_account_name, a.bank_account_num back_bank_account_num, cb.bank_name back_bank_name FROM fct_quotation_cashflow cc join fct_contract c on c.contract_id = cc.contract_id LEFT JOIN csh_bank_account a ON c.fct_payment_account_id=a.bank_account_id LEFT JOIN csh_bank cb on cb.bank_id=a.bank_id WHERE cc.cf_direction ='INFLOW' AND nvl(cc.write_off_flag,'NOT') !='FULL' and ((c.contract_status in('INCEPT')) or (cc.times=0 and c.contract_status in('SIGN'))) AND c.data_class = 'NORMAL' AND cc.cf_status = 'RELEASE' ) t
1=1 AND t.company_id=#{request.companyId}
and (t.contract_number LIKE concat('%',concat(#{contractNameOrNumber},'%') ) or t.contract_name LIKE concat('%',concat(#{contractNameOrNumber},'%') ))
and (t.bp_name LIKE concat('%',concat(#{bpNameOrCode},'%') ) or t.bp_code LIKE concat('%',concat(#{bpNameOrCode},'%') ) )
and t.approval_number LIKE concat('%',concat(#{approvalNumber},'%') )
and t.cf_item_desc = #{cfItemDesc}
and t.due_date >= #{dueDateFrom}
and t.company_id = #{companyId}
and t.unit_id = #{unitId}
and t.due_date <= #{dueDateTo}
and ((month(t.due_date) = month(sysdate) and year(t.due_date) = year(sysdate)) or (t.due_amount > t.received_amount and t.due_date < sysdate))
AND t.write_off_flag in
#{item}
order by t.due_date

SELECT t.*, CASE WHEN t.write_off_flag='NOT' THEN '未核销' WHEN t.write_off_flag='PARTIAL' THEN '部分核销' WHEN t.write_off_flag='FULL' THEN '完全核销' END AS write_off_flag_desc FROM ( ( SELECT cc.*, c.project_id, c.contract_number, c.contract_name, fp.approval_number, c.document_category, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, hbm.bp_name, hbm.bp_code, c.currency, ( SELECT currency_name FROM fnd_currency fc WHERE fc.currency_code = c.currency ) currency_name, CASE WHEN cc.received_amount=0 THEN 'NOT' ELSE 'PARTIAL' END write_off_flag, c.company_id, null back_bank_name, null back_bank_account_num, fe.name manager_name, fou.unit_name FROM con_contract c JOIN hls_bp_master hbm ON hbm.bp_id=c.tenant_id JOIN prj_project fp ON fp.project_id = c.project_id join fnd_employee fe on fp.employee_id=fe.employee_id join fnd_org_unit fou on fou.unit_id=fp.unit_id JOIN ( SELECT f.contract_id, f.due_date, (select f.times||'/'||max(ccc.times) from con_contract_cashflow ccc where ccc.CONTRACT_ID=f.CONTRACT_ID) times_total, f.due_date AS due_date_desc, SUM(f.due_amount) due_amount, SUM(nvl(f.received_amount,0)) received_amount, SUM(nvl(f.due_amount,0) - nvl(f.received_amount,0)) surplus_amount, SUM(nvl(f.principal,0)) the_principal, SUM(nvl(f.interest,0)) the_interest, nvl(SUM( CASE WHEN f.cf_item=51 THEN f.due_amount ELSE 0 END) ,0) the_margin, nvl(SUM( CASE WHEN f.cf_item=4 THEN f.due_amount ELSE 0 END) ,0) the_consulting_service_fee, SUM(CASE WHEN f.CF_ITEM =3 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_lease_charge, SUM(CASE WHEN f.CF_ITEM =8 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_residual_value, SUM(CASE WHEN f.CF_ITEM =2 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_down_payment, SUM(CASE WHEN f.cf_item =10 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_pre_rent, SUM(CASE WHEN f.cf_item =9 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_penalty_interest FROM con_contract_cashflow f, con_contract c WHERE c.contract_id=f.contract_id AND f.cf_direction ='INFLOW' AND nvl(f.write_off_flag,'NOT') !='FULL' AND f.cf_status = 'RELEASE' AND c.contract_status in('INCEPT','SIGN','LOAN') GROUP BY f.contract_id, f.due_date, f.times) cc ON cc.contract_id=c.contract_id WHERE c.write_off_able_flag='Y' AND c.data_class = 'NORMAL') UNION ( SELECT cc.*, c.project_id, c.contract_number, c.contract_name, fp.approval_number, c.document_category, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, ( SELECT MAX(hbm.bp_name) FROM fct_project_bp fpb , hls_bp_master hbm WHERE fpb.project_id=c.project_id AND fpb.bp_id=hbm.bp_id AND fpb.CREDIT_GRANTOR_PARTY='Y') bp_name, ( SELECT MAX(hbm.bp_code) FROM fct_project_bp fpb , hls_bp_master hbm WHERE fpb.project_id=c.project_id AND fpb.bp_id=hbm.bp_id AND fpb.CREDIT_GRANTOR_PARTY='Y') bp_code, c.currency, ( SELECT currency_name FROM fnd_currency fc WHERE fc.currency_code = c.currency ) currency_name, CASE WHEN cc.received_amount=0 THEN 'NOT' ELSE 'PARTIAL' END write_off_flag, c.company_id, ( select cb.bank_name from csh_bank cb where cba.bank_id = cb.bank_id ) AS back_bank_name, cba.bank_account_num back_bank_account_num, fe.name manager_name, fou.unit_name FROM fct_contract c JOIN fct_project fp ON fp.project_id = c.project_id join fnd_employee fe on fp.employee_id=fe.employee_id join fnd_org_unit fou on fou.unit_id=fp.unit_id LEFT JOIN csh_bank_account cba ON cba.bank_account_id = c.fct_payment_account_id JOIN ( SELECT f.contract_id, f.due_date,
(select f.times||'/'||max(fqc.times) from fct_quotation_cashflow fqc where fqc.CONTRACT_ID=f.CONTRACT_ID)times_total, f.due_date AS due_date_desc, SUM(f.due_amount) due_amount, SUM(nvl(f.received_amount,0)) received_amount, SUM(nvl(f.due_amount,0) - nvl(f.received_amount,0)) surplus_amount, nvl(SUM( CASE WHEN f.cf_item=54 THEN f.due_amount ELSE 0 END) ,0) the_principal, nvl(SUM( CASE WHEN f.cf_item=55 THEN f.due_amount ELSE 0 END) ,0) the_interest, nvl(SUM( CASE WHEN f.cf_item=51 THEN f.due_amount ELSE 0 END) ,0) the_margin, nvl(SUM( CASE WHEN f.cf_item=57 THEN f.due_amount ELSE 0 END) ,0) the_consulting_service_fee, 0 the_lease_charge, 0 the_residual_value, 0 the_down_payment, 0 the_pre_rent, SUM(CASE WHEN f.cf_item =45 THEN nvl(f.DUE_AMOUNT, 0) ELSE 0 END) the_penalty_interest FROM fct_quotation_cashflow f, fct_contract c WHERE c.contract_id=f.contract_id AND f.cf_direction ='INFLOW' AND nvl(f.write_off_flag,'NOT') !='FULL' AND f.cf_status = 'RELEASE' AND (( c.contract_status IN('INCEPT')) OR ( f.times=0 AND c.contract_status IN('SIGN'))) GROUP BY f.contract_id, f.due_date, f.times) cc ON cc.contract_id=c.contract_id WHERE c.data_class = 'NORMAL') ) t
1=1 AND t.company_id=#{request.companyId}
and (t.contract_number LIKE concat('%',concat(#{contractNameOrNumber},'%') ) or t.contract_name LIKE concat('%',concat(#{contractNameOrNumber},'%') ))
and (t.bp_name LIKE concat('%',concat(#{bpNameOrCode},'%') ) or t.bp_code LIKE concat('%',concat(#{bpNameOrCode},'%') ) )
and t.approval_number LIKE concat('%',concat(#{approvalNumber},'%') )
and t.due_date >= #{dueDateFrom}
