ncipal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format FROM fct_quotation_cashflow cc, fct_contract c WHERE cc.cf_direction ='INFLOW' AND nvl(cc.write_off_flag,'NOT') !='FULL' AND c.contract_id = cc.contract_id AND cc.times!=0 AND c.data_class = 'NORMAL' AND c.contract_status IN('INCEPT') AND cc.cf_status = 'RELEASE' UNION SELECT cc.contract_id, c.project_id, c.contract_number, c.document_category, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, cc.times, cc.due_date, --cast(cc.due_date as char) as due_date_desc, cc.due_date AS due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) AS due_amount_format, cc.cf_item, cc.cf_type, cc.cashflow_id, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = cc.cf_item AND ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format FROM con_contract_cashflow cc, con_contract c WHERE cc.cf_direction ='INFLOW' AND nvl(cc.write_off_flag,'NOT') !='FULL' AND c.contract_id = cc.contract_id AND c.write_off_able_flag='N' AND cc.times =0 AND c.data_class = 'NORMAL' AND c.contract_status IN('SIGN') AND cc.cf_status = 'RELEASE' UNION SELECT cc.contract_id, c.project_id, c.contract_number, c.document_category, ( SELECT hdc.description FROM HLS_DOCUMENT_CATEGORY hdc WHERE hdc.document_category = c.document_category) AS document_category_desc, cc.times, cc.due_date, --cast(cc.due_date as char) as due_date_desc, cc.due_date AS due_date_desc, cc.due_amount, FORMAT(cc.due_amount,2) AS due_amount_format, cc.cf_item, cc.cf_type, cc.quotation_cashflow_id AS cashflow_id, ( SELECT ci.description FROM hls_cashflow_item ci WHERE ci.cf_item = cc.cf_item AND ci.cf_type=cc.cf_type) cf_item_desc, (nvl(cc.due_amount,0) - nvl(cc.received_amount,0)) surplus_amount, FORMAT((nvl(cc.due_amount,0) - nvl(cc.received_amount,0)),2) surplus_amount_format, (nvl(cc.principal,0) - nvl(cc.received_principal,0)) principal, FORMAT((nvl(cc.principal,0) - nvl(cc.received_principal,0)),2) principal_format, (nvl(cc.interest,0) - nvl(cc.received_interest,0)) interest, FORMAT((nvl(cc.interest,0) - nvl(cc.received_interest,0)),2) interest_format FROM fct_quotation_cashflow cc, fct_contract c WHERE cc.cf_direction ='OUTFLOW' AND nvl(cc.write_off_flag,'NOT') !='FULL' AND c.contract_id = cc.contract_id AND cc.times =0 AND c.data_class = 'NORMAL' AND c.contract_status IN('SIGN') AND cc.cf_status = 'RELEASE' AND cc.cf_item=52 ) t
