AND to_char(t1.due_date,'YYYY-MM-DD') >= to_char(#{dueDateFrom},'YYYY-MM-DD')
AND to_char(t1.due_date,'YYYY-MM-DD') <= to_char(#{dueDateTo},'YYYY-MM-DD')
and t1.cf_type = #{cfType}
