select ccc.cashflow_id, ccc.times, ccc.contract_id, ccc.cf_item, (select h.description from hls_cashflow_item h where h.cf_item = ccc.cf_item)cf_item_n, ccc.cf_type, ccc.cf_direction, case when ccc.cf_direction = 'INFLOW' then '流入' else '流出' end cf_direction_n, ccc.due_date, ccc.due_amount, ccc.net_due_amount, ccc.vat_due_amount, ccc.LAST_RECEIVED_DATE, ccc.RECEIVED_AMOUNT, ccc.overdue_status, ccc.NET_INTEREST, ccc.VAT_INTEREST, (case when ccc.overdue_status = 'Y' then'是' else '否' end)overdue_status_n, ccc.principal, ccc.interest, ccc.received_principal, ccc.received_interest, (nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0))outstanding_amount, (nvl(ccc.principal,0) - nvl(ccc.received_principal,0))outstanding_principal, (nvl(ccc.interest,0) - nvl(ccc.received_interest,0))outstanding_interest, c.contract_number, c.project_id from con_contract_cashflow ccc,con_contract c
ccc.contract_id = c.contract_id and c.project_id = #{projectId}
