SELECT TAB.*, CASE WHEN TAB.occupy_items IS NULL THEN '未占用' ELSE '已占用' END AS occupy_status FROM ( SELECT ccc.cashflow_id, ccc.times, ccc.contract_id, ccc.cf_item, ( SELECT h.description FROM hls_cashflow_item h WHERE h.cf_item = ccc.cf_item ) AS cf_item_n, ccc.cf_type, ccc.cf_direction, CASE WHEN ccc.cf_direction = 'INFLOW' THEN '流入' ELSE '流出' END AS cf_direction_n, ccc.due_date, ccc.due_amount, ccc.net_due_amount, ccc.vat_due_amount, ccc.LAST_RECEIVED_DATE, ccc.RECEIVED_AMOUNT, ccc.overdue_status, ccc.NET_INTEREST, ccc.VAT_INTEREST, CASE WHEN ccc.overdue_status = 'Y' THEN '是' ELSE '否' END AS overdue_status_n, ccc.principal, ccc.interest, ccc.received_principal, ccc.received_interest, nvl( ccc.due_amount, 0 ) - nvl( ccc.received_amount, 0 ) AS outstanding_amount, nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) AS outstanding_principal, nvl( ccc.interest, 0 ) - nvl( ccc.received_interest, 0 ) AS outstanding_interest, ( SELECT wm_concat(DISTINCT V.occupy_items ) AS occupy_items FROM ( SELECT cap.PRODUCT_NUMBER AS occupy_items, caap.pack_date_from AS date_from, caap.pack_date_to AS date_to, caap.contract_id as contract_id FROM ct_abs_product cap, ct_abs_assets_package caap WHERE cap.pack_id = caap.pack_id UNION SELECT lc.CONTRACT_NUMBER AS occupy_items, clcp.PLEDGE_TIMES_FROM AS date_from, clcp.PLEDGE_TIMES_TO AS date_to, clcp.pledge_doc_id as contract_id FROM lon_contract lc, ct_lon_contract_pledge clcp WHERE lc.CONTRACT_ID = clcp.CONTRACT_ID ) V WHERE V.date_from <= ccc.DUE_DATE AND V.date_to >= ccc.DUE_DATE and V.contract_id = ccc.contract_id and ccc.cf_direction = 'INFLOW' ) AS occupy_items FROM con_contract_cashflow ccc
ccc.contract_id = #{contractId}
and ccc.cf_direction = #{cfDirection}
ORDER BY ccc.times,ccc.cf_item ) TAB

select tt.* from ( SELECT ccc.*, nvl((SELECT SUM(nvl(o.write_off_due_amount, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0) write_off_due_amount, nvl((SELECT SUM(nvl(o.write_off_principal, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0) write_off_principal, nvl((SELECT SUM(nvl(o.write_off_interest, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0)write_off_interest FROM con_contract_cashflow ccc LEFT JOIN con_contract cc on ccc.contract_id = cc.contract_id LEFT JOIN hls_cashflow_item hci on ccc.cf_item = hci.cf_item WHERE ccc.contract_id = #{contractId} AND ccc.cf_status = 'RELEASE' AND to_char(ccc.due_date,'yyyymm') < to_char(#{dayEndDate},'yyyymm') AND hci.calc_penalty = 'Y' and cc.contract_status = 'INCEPT' and ccc.write_off_flag!='FULL' union SELECT ccc.*, nvl((SELECT SUM(nvl(o.write_off_due_amount, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0) write_off_due_amount, nvl((SELECT SUM(nvl(o.write_off_principal, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0) write_off_principal, nvl((SELECT SUM(nvl(o.write_off_interest, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.cashflow_id = ccc.cashflow_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' and ct.transaction_date <= ccc.due_date), 0)write_off_interest FROM con_contract_cashflow ccc LEFT JOIN con_contract cc on ccc.contract_id = cc.contract_id LEFT JOIN hls_cashflow_item hci on ccc.cf_item = hci.cf_item WHERE ccc.contract_id = #{contractId} AND ccc.cf_status = 'RELEASE' AND to_char(ccc.due_date,'yyyymm') < to_char(#{dayEndDate},'yyyymm') AND hci.calc_penalty = 'Y' and ccc.write_off_flag!='FULL' and cc.contract_status = 'INCEPT' AND (SELECT trunc(MAX(O.CREATION_DATE)) FROM csh_write_off O WHERE O.cashflow_id=CCC.cashflow_id)>=#{dayEndDate}
) tt
ORDER BY tt.times, tt.due_date

select ccc.*, (select ci.description from hls_cashflow_item ci where ci.cf_item = ccc.cf_item and ci.cf_type = ccc.cf_type) cf_item_n, (select ct.description from hls_cashflow_type ct where ct.cf_direction = ccc.cf_direction and ct.cf_type = ccc.cf_type) cf_type_n, (SELECT scvb.MEANING FROM scvb WHERE scvb.CODE = 'CON.CASHFLOW_WRITE_OFF_FLAG' AND scvb.code_value = ccc.write_off_flag ) AS write_off_flag_n, (select scvb.meaning from scvb where scvb.code = 'HLS.CASHFLOW_DIRECTION' and scvb.code_value = ccc.cf_direction ) cf_direction_n, (select scvb.meaning from scvb where scvb.code = 'HLS.CASHFLOW_DIRECTION' and scvb.code_value = ccc.cf_direction ) cf_direction_desc, (select scvb.meaning from scvb where scvb.code = 'CON.CF_STATUS' and scvb.code_value = ccc.cf_status ) cf_status_n, ccc.cf_direction cf_direction_pic
from con_contract_cashflow ccc where 1 = 1
and ccc.contract_id = #{contractId}
and ccc.generated_source_doc_id = #{generatedSourceDocId}
and ccc.generated_source = #{generatedSource}
order by ccc.times,ccc.cf_item asc

select t.* from (select ccc.cashflow_id,cc.contract_number payment_number,pp.contract_number , (select t.company_full_name from fnd_company t where t.company_id=pp.company_spv) company_spv_n, pp.contract_name, (select bp_code from hls_bp_master where bp_id=pp.tenant_id) as bp_code, (select bp_name from hls_bp_master where bp_id=pp.tenant_id) as bp_name, (select s.description from sys_user s where s.user_id = pp.host_project_manager) host_project_manager_n, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = pp.host_unit_id) host_unit_name, ccc.cf_item, ccc.TIMES,(select h.description from hls_cashflow_item h where h.cf_item = ccc.cf_item)cf_item_n, ccc.due_date due_month,ccc.due_date,ccc.due_amount,ccc.received_amount, (ccc.due_amount - ccc.received_amount) outstanding_amount, (select pq.currency from prj_quotation pq where pq.source_document_id = cc.contract_id and pq.source_document_category = 'CON_CONTRACT' and rownum=1 ) currency, ( select fc.currency_name from fnd_currency fc,prj_quotation pq where pq.source_document_id = cc.contract_id and fc.currency_code = pq.currency and pq.source_document_category = 'CON_CONTRACT' and rownum=1 ) currency_name, (select max(cwo.csh_transaction_id) from csh_write_off cwo where ccc.cashflow_id = cwo.cashflow_id ) transaction_id from con_contract_cashflow ccc,con_contract cc,prj_project pp where ccc.contract_id = cc.contract_id and pp.project_id = cc.project_id and ccc.cf_direction = 'INFLOW' and pp.data_class = 'VIRTUAL_CON') t
