SELECT ccc.*, ( CASE WHEN ccc.stage_type = '租前期' THEN 2 WHEN ccc.cf_item = 0 THEN 0 WHEN ccc.times = 0 THEN 1 WHEN ccc.stage_type = '宽限期' THEN 3 WHEN ccc.stage_type = '租赁期' THEN 4 ELSE 5 END ) stage_type_seq, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 3 AND cc.CF_TYPE = 3 ) lease_charge, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 4 AND cc.CF_TYPE = 4 ) lease_mgt_fee, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 8 AND cc.cf_type = 8 ) residual_value, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 51 AND cc.cf_type = 5 ) deposit, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 52 AND cc.cf_type = 5 ) deposit_return, ( SELECT cc.due_amount FROM con_contract_cashflow cc WHERE cc.times = ccc.times AND cc.contract_id = ccc.contract_id AND cc.cf_item = 10 AND cc.cf_type = 10 ) pre_lease_fee FROM con_contract_cashflow ccc
