select * from ( SELECT ccf.cashflow_id, cc.contract_id, cc.PROJECT_ID, cc.contract_name, cc.contract_number, cc.unit_id, cc.employee_id, ccf.times, ccf.cf_item, ccf.due_amount, ccf.due_date, ccf.calc_date, ccf.overdue_max_days, ccf.write_off_flag, '' as print_status FROM con_contract_cashflow ccf, con_contract cc WHERE cc.contract_id = ccf.contract_id and cc.PROJECT_ID = #{contractId}
