SELECT * FROM ( SELECT cc.contract_number, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = pp.tenant_id ) AS bp_name, ccc.cashflow_id, ccc.contract_id, ccc.times, ccc.due_date, ccc.cf_item, ( SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = ccc.cf_item AND ccc.cf_type = i.cf_type ) cf_item_n, ccc.due_amount, ccc.write_off_flag, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CON.CASHFLOW_WRITE_OFF_FLAG' AND v.code_value = ccc.write_off_flag ) write_off_flag_n, ccc.received_amount, ccc.expense_item, ( SELECT wm_concat( ccc1.due_amount ) FROM hls_cashflow_item i, con_contract_cashflow ccc1 WHERE i.cf_item = ccc1.cf_item AND ccc1.cf_type = i.cf_type AND ccc1.contract_id = ccc.contract_id AND ccc1.times = ccc.times AND i.description = ccc.expense_item ) AS expense_item_amount FROM con_contract_cashflow ccc, con_contract cc, prj_project pp WHERE ccc.contract_id = cc.contract_id AND cc.project_id = pp.project_id AND ccc.cf_item IN ( 131, 132 ) ) V
