select t1.* from ( select cc.project_id, cc.contract_number as payment_number, pp.contract_number, pp.contract_name, pp.business_type, ccc.cashflow_id, case when pp.business_type = 'T+0_LEASE_FACTORING' or pp.business_type = 'T+N_LEASE_FACTORING' then ppb_fct.bp_name when pp.business_type = 'LEASE_WITHOUT_RECOURSE_IN' or pp.business_type = 'OPERATING_LEASE_WITHOUT_RECOURSE_IN' then ppb_ast.bp_name else ppb_tenant.bp_name end as bp_name, su.description AS host_project_manager_n, fou.unit_name AS unit_name, equipment_amount.equipment_amount, ccc_total_time.lease_times, ccc.times, ccc.cf_item, ( SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = ccc.cf_item and i.cf_type = ccc.cf_type) cf_item_n, ccc.due_date, ccc.due_amount, ccc.net_due_amount, ccc.vat_due_amount, ccc.principal, ccc.net_principal, ccc.vat_principal, ccc.interest, ccc.net_interest, ccc.vat_interest, ccc.received_amount, due_amount - nvl(ccc.received_amount,0) as un_received_amount, nvl(ccc.overdue_amount,0) as overdue_amount, nvl(sum_un_received_principal.sum_un_received_principal,0) as sum_balance_principal, ccc.overdue_status, ccc.overdue_max_days, (case when ccc.overdue_status ='Y' then '是' else '否' end) overdue_status_n, ccc.received_principal, ccc.received_interest, (select nvl(sum(ccc1.due_amount),0) from con_contract_cashflow ccc1 where ccc1.contract_id = ccc.contract_id and ccc1.times = ccc.times and ccc1.cf_item = 9) as fine_amount, (select max(write_off_date) from csh_write_off cwo where cwo.cashflow_id = ccc.cashflow_id and cwo.reversed_flag = 'N' ) as write_off_date, (select max(ct.transaction_date) from csh_write_off cwo,csh_transaction ct where cwo.cashflow_id = ccc.cashflow_id and cwo.reversed_flag= 'N' and ct.transaction_id=cwo.csh_transaction_id) as transaction_date, ( CASE WHEN ( SELECT count(1) FROM ct_lon_contract_pledge ct WHERE ct.pledge_contract_number = cc.contract_number AND ccc.due_date BETWEEN ct.PLEDGE_TIMES_FROM AND ct.PLEDGE_TIMES_TO ) > 0 THEN 'Y' ELSE 'N' END ) pledge_flag, ( CASE WHEN ( SELECT count(1) FROM ct_lon_contract_pledge ct WHERE ct.pledge_contract_number = cc.contract_number AND ccc.due_date BETWEEN ct.PLEDGE_TIMES_FROM AND ct.PLEDGE_TIMES_TO ) > 0 THEN '是' ELSE '否' END ) pledge_flag_n
from con_contract_cashflow ccc , con_contract cc left join (select max(times) as lease_times,ccc1.contract_id from con_contract_cashflow ccc1 group by ccc1.contract_id) ccc_total_time on ccc_total_time.contract_id = cc.contract_id left join (select sum(ccc1.due_amount) as equipment_amount,ccc1.contract_id from con_contract_cashflow ccc1 where ccc1.cf_item = 0 group by ccc1.contract_id) equipment_amount on equipment_amount.contract_id = cc.contract_id left join (select nvl( sum( CASE WHEN ( SELECT q.BONDED_LEASE_FLAG FROM prj_quotation q WHERE q.QUOTATION_ID = ccc1.QUOTATION_ID ) = 'Y' THEN nvl(ccc1.NET_PRINCIPAL, 0) ELSE nvl(ccc1.principal, 0) END ),0) as sum_un_received_principal,ccc1.contract_id from con_contract_cashflow ccc1 where ccc1.cf_item in (1,11) AND ccc1.CF_STATUS = 'RELEASE' and ccc1.WRITE_OFF_FLAG = 'NOT' group by ccc1.contract_id) sum_un_received_principal on sum_un_received_principal.contract_id = cc.contract_id, prj_project pp left join (select wm_concat(hbm.bp_name) as bp_name,ppb.project_id from hls_bp_master hbm ,prj_project_bp ppb where hbm.bp_id = ppb.bp_id and ppb.bp_type = 'TENANT' group by ppb.project_id ) ppb_tenant on pp.project_id = ppb_tenant.project_id left join (select wm_concat(hbm.bp_name) as bp_name,ppb.project_id from hls_bp_master hbm ,prj_project_bp ppb where hbm.bp_id = ppb.bp_id and ppb.bp_type = 'ACCOUNTS_RECEIVABLE' group by ppb.project_id ) ppb_fct on pp.project_id = ppb_fct.project_id left join (select wm_concat(hbm.bp_name) as bp_name,ppb.project_id from hls_bp_master hbm ,prj_project_bp ppb where hbm.bp_id = ppb.bp_id and ppb.bp_type = 'ASSET_TRANSFEROR' group by ppb.project_id ) ppb_ast on pp.project_id = ppb_ast.project_id left join sys_user su on su.user_id = pp.host_project_manager left join fnd_org_unit fou on fou.unit_id = pp.unit_id where ccc.contract_id = cc.contract_id and cc.project_id = pp.project_id and cc.contract_status in ('INCEPT','ET','TERMINATE') and cc.data_class='NORMAL' and ccc.cf_direction = 'INFLOW' and ccc.cf_status = 'RELEASE')t1
1=1
and t1.bp_name LIKE concat('%',concat(#{bpName},'%'))
