SELECT t1.* FROM (SELECT t.contract_id, t.cashflow_id, cc.contract_number, cc.contract_name, t.times, t.due_date, t.due_amount, t.cf_item, t.cf_type, t.cf_status, t.cf_direction, (SELECT i.description FROM hls_cashflow_item i WHERE i.cf_item = t.cf_item AND i.cf_type = t.cf_type ) cf_item_n, ( t.due_amount - nvl(t.received_amount, 0) - ifnull(t.BLOCK_AMOUNT,0) ) AS surplus_amount, ( nvl(t.principal,0) - nvl(t.received_principal, 0) -nvl(t.BLOCK_PRINCIPAL,0)) AS surplus_principal, ( nvl(t.interest,0) - nvl(t.received_interest, 0) - nvl(t.BLOCK_INTEREST,0)) AS surplus_interest, cc.BP_ID_TENANT as bp_id, ( SELECT bp.bp_name FROM hls_bp_master bp WHERE cc.bp_id_tenant = bp.bp_id ) bp_name, ( SELECT bp.bp_name FROM hls_bp_master bp WHERE cc.FACTORY_ID = bp.bp_id ) bp_name_factory, ( SELECT bp.bp_name FROM hls_bp_master bp WHERE cc.MANUFACTURER_ID = bp.bp_id ) bp_name_facturer FROM CON_CONTRACT cc, con_contract_cashflow t WHERE cc.CONTRACT_ID = t.CONTRACT_ID and cc.contract_status in ('SIGN','INCEPT') and cc.data_class = 'NORMAL' AND t.write_off_flag!='FULL' and (cc.SUBSTITUTE_RECEIPT_FLAG = 'N' or (cc.SUBSTITUTE_RECEIPT_FLAG = 'Y' and t.CF_TYPE not in (1,9,8)) or (cc.SUBSTITUTE_RECEIPT_FLAG = 'Y' and t.cf_item in (1,11,13,9) and exists (select 1 from con_contract_cashflow ccf where ccf.contract_id = cc.contract_id and ccf.cf_item in (11,13)) )) and not exists (select 1 from CSH_PAYMENT_REQ_DT dt where dt.SOURCE_DOC_CATEGORY = 'CON_CONTRACT' and dt.SOURCE_DOC_LINE_ID = t.cashflow_id and exists(select 1 from CSH_PAYMENT_REQ_HD hd, CSH_PAYMENT_REQ_LN ln where hd.PAYMENT_REQ_ID = ln.PAYMENT_REQ_ID and ln.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID and hd.PAYMENT_REQ_STATUS != 'BACK' and nvl(ln.PAY_STATUS, 'NEW') != 'BACK')) ) t1 where 1=1
and t1.contract_id = #{contractId}
and t1.bp_name like #{bpName}
and t1.contract_number like #{contractNumber}
and t1.bp_name_factory like #{bpNameFactory}
and t1.bp_name_facturer like #{bpNameFacturer}
and t1.cf_status = #{cfStatus}
and t1.cf_direction = #{cfDirection}
and t1.cashflow_id not in
#{item}
