and t1.cf_item != #{nCfItem}
and t1.cf_type = #{cfType}
and t1.cf_type != #{nCfType}
order by t1.contract_number,t1.times

SELECT t1.*,(IFNULL(t1.due_amount, 0) - ifnull(t1.applied_pay_amount,0)) residual_amount FROM (SELECT t.contract_id, t.contract_name, f.cashflow_id, f.times, t.contract_number, t.tenant_id, pq.quotation_number, (SELECT b.bp_code FROM hls_bp_master b WHERE b.bp_id = t.tenant_id) bp_id_tenant_c, (SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = t.tenant_id) tenant_name, h.description cf_item_n, h.cf_item, IFNULL(f.due_amount,0)due_amount, t.currency, (select currency_name from fnd_currency where currency_code = t.currency) currency_n, f.due_date, -- IFNULL(f.received_amount,0)received_amount, (CASE WHEN pq.quotation_type = 'MAJOR' THEN IFNULL(f.received_amount, 0) ELSE (SELECT sum( IFNULL(ccc.received_amount, 0) ) FROM con_contract_cashflow ccc, con_contract_spin ccs, prj_quotation pq1 WHERE ccc.contract_id = f.contract_id AND pq1.QUOTATION_ID = ccs.quotation_id AND ccs. STATUS = 'APPROVED' AND ccc.generated_source_doc_id = pq1.quotation_id AND pq1.enabled_flag = 'Y' AND ccc.cf_item = 0) END) received_amount, (IFNULL(f.due_amount, 0) - IFNULL(f.received_amount, 0))surplus_amount, -- (IFNULL((SELECT SUM(l.amount_paid) -- FROM csh_payment_req_ln l, csh_payment_req_hd h -- WHERE l.source_doc_line_id = f.cashflow_id -- AND l.payment_req_id = h.payment_req_id -- AND h.payment_req_status = 'APPROVED'), -- 0) + -- IFNULL((SELECT SUM(l.amount) -- FROM csh_payment_req_ln l, csh_payment_req_hd h -- WHERE l.source_doc_line_id = f.cashflow_id -- AND l.payment_req_id = h.payment_req_id -- AND h.payment_req_status IN('NEW','APPROVING','APPROVED') -- AND IFNULL(l.submit_flag,'N') ='N'), -- 0)) applied_pay_amount, ( CASE WHEN pq.quotation_type = 'MAJOR' THEN( nvl(( SELECT SUM(l.amount) FROM csh_payment_req_ln l,csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ( 'NEW','APPROVING','APPROVED') ),0) )ELSE nvl(( SELECT SUM(l.amount) FROM con_contract_cashflow ccc,con_contract_spin ccs,prj_quotation pq1,csh_payment_req_ln l,csh_payment_req_hd h WHERE ccc.cashflow_id = f.cashflow_id AND pq1.QUOTATION_ID = ccs.quotation_id AND ccs. STATUS = 'APPROVED' AND ccc.generated_source_doc_id = pq1.quotation_id AND pq1.enabled_flag = 'Y' AND ccc.cf_item = 0 AND l.source_doc_line_id = ccc.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ('NEW','APPROVING','APPROVED') ),0) END) applied_pay_amount, (select q.quotation_id from prj_quotation q where q.quotation_id = f.generated_source_doc_id and f.generated_source = 'PRJ_QUOTATION')quotation_id FROM con_contract t, con_contract_cashflow f, hls_cashflow_item h, prj_quotation pq WHERE t.contract_id = f.contract_id AND f.cf_item = h.cf_item and f.cf_type = h.cf_type AND h.cf_direction = 'OUTFLOW' AND f.write_off_flag != 'FULL' AND f.cf_status = 'RELEASE' AND IFNULL(f.due_amount, 0) - IFNULL(f.received_amount, 0) > 0 AND f.cf_direction = 'OUTFLOW' AND (IFNULL(f.due_amount, 0) - IFNULL((SELECT SUM(l.amount) FROM csh_payment_req_ln l, csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status = 'APPROVED'), 0) - IFNULL((SELECT SUM(l.amount) FROM csh_payment_req_ln l, csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ('NEW','APPROVING')),0)) > 0 AND t.data_class = 'NORMAL' AND t.contract_status NOT IN ('CANCEL', 'PENDING', 'NEW') and f.generated_source_doc_id = pq.quotation_id and pq.source_document_category = 'CONTRACT' and pq.enabled_flag = 'Y' ) t1
1=1 and (IFNULL(t1.due_amount, 0) > ifnull(t1.applied_pay_amount,0))
AND t1.contract_number >= #{contractNumberFrom}
AND t1.contract_number <= #{contractNumberTo}
