SELECT t1.*,(nvl(t1.due_amount, 0) - nvl(t1.applied_pay_amount, 0)) residual_amount FROM (SELECT t.contract_id, t.contract_name,
t.PAYMENT_BP_ID, t.PAYMENT_BP_TYPE, t.LEASE_CHANNEL, t.PROJECT_ID, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = t.PAYMENT_BP_ID) payment_bp_name, t.TENANT_ID, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = t.tenant_id) tenant_name, t.factory_id, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = t.factory_id) factory_name, t.manufacturer_id, (SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = t.manufacturer_id) manufacturer_name,
( SELECT fe.EMPLOYEE_CODE FROM fnd_employee fe WHERE fe.employee_id = (select prj.employee_id from PRJ_PROJECT prj where prj.PROJECT_ID = t.PROJECT_ID ) ) project_manager_code,
(SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'PRJ.ACCEPTANCE_TERM' AND v.code_value = pq.acceptance_term) acceptance_term_n,
f.cashflow_id, f.times, t.contract_number, pq.quotation_number, h.description cf_item_n, h.cf_item, nvl(f.due_amount, 0) due_amount, t.currency, (select currency_name from fnd_currency where currency_code = t.currency) currency_name, nvl(f.due_date,f.fin_income_date) due_date, (CASE WHEN pq.quotation_type = 'MAJOR' THEN nvl(f.received_amount, 0) ELSE nvl( (SELECT sum( nvl(ccc.received_amount, 0) ) FROM con_contract_cashflow ccc, con_contract_spin ccs, prj_quotation pq1 WHERE ccc.contract_id = f.contract_id AND pq1.QUOTATION_ID = ccs.quotation_id AND ccs.STATUS = 'APPROVED' AND ccc.generated_source_doc_id = pq1.quotation_id AND pq1.enabled_flag = 'Y' AND ccc.cf_item = 0), 0) END) received_amount, (nvl(f.due_amount, 0) - nvl(f.received_amount, 0)) surplus_amount, ( CASE WHEN pq.quotation_type = 'MAJOR' THEN ( nvl(( SELECT SUM(l.amount) FROM csh_payment_req_ln l, csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ('NEW', 'APPROVING', 'APPROVED') ), 0) ) ELSE nvl(( SELECT SUM(l.amount) FROM con_contract_cashflow ccc, con_contract_spin ccs, prj_quotation pq1, csh_payment_req_ln l, csh_payment_req_hd h WHERE ccc.cashflow_id = f.cashflow_id AND pq1.QUOTATION_ID = ccs.quotation_id AND ccs.STATUS = 'APPROVED' AND ccc.generated_source_doc_id = pq1.quotation_id AND pq1.enabled_flag = 'Y' AND ccc.cf_item = 0 AND l.source_doc_line_id = ccc.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ('NEW', 'APPROVING', 'APPROVED') ), 0) END) applied_pay_amount, ( SELECT nvl(SUM(flow.due_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 51 AND flow.CF_TYPE = 5 ) AS deposit_due_amount, --保证金 (SELECT nvl(SUM(flow.received_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 51 AND flow.CF_TYPE = 5 ) AS deposit_received_amount, --已收保证金 ( SELECT nvl(SUM(flow.due_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 65 AND flow.CF_TYPE = 65 ) AS service_charge_due_amount, --服务费 ( SELECT nvl(SUM(flow.received_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 65 AND flow.CF_TYPE = 65 ) AS service_charge_received_amount, --已收服务费 ( SELECT nvl(SUM(flow.due_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 66 AND flow.CF_TYPE = 65 ) AS service_fee_due_amount, --服务费（贴息） ( SELECT nvl(SUM(flow.received_amount), 0) FROM con_contract_cashflow flow WHERE flow.contract_id = t.contract_id AND flow.cf_item = 66 AND flow.CF_TYPE = 65 ) AS service_fee_received_amount, --已收服务费（贴息）
(select q.quotation_id from prj_quotation q where q.quotation_id = f.generated_source_doc_id and f.generated_source = 'PRJ_QUOTATION') quotation_id FROM con_contract t, con_contract_cashflow f, hls_cashflow_item h, prj_quotation pq WHERE t.contract_id = f.contract_id AND f.cf_item = h.cf_item and f.cf_type = h.cf_type AND h.cf_direction = 'OUTFLOW' AND f.write_off_flag != 'FULL' AND f.cf_status = 'RELEASE' AND nvl(f.due_amount, 0) - nvl(f.received_amount, 0) > 0 AND f.cf_direction = 'OUTFLOW' AND (nvl(f.due_amount, 0) - nvl((SELECT SUM(l.amount) FROM csh_payment_req_ln l, csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status = 'APPROVED'), 0) - nvl((SELECT SUM(l.amount) FROM csh_payment_req_ln l, csh_payment_req_hd h WHERE l.source_doc_line_id = f.cashflow_id AND l.payment_req_id = h.payment_req_id AND h.payment_req_status IN ('NEW', 'APPROVING')), 0)) > 0 AND t.data_class = 'NORMAL' AND t.contract_status NOT IN ('CANCEL', 'PENDING', 'NEW') and f.generated_source_doc_id = pq.quotation_id AND pq.source_document_category in ('PRJ_QUOTATION','CON_CONTRACT') AND pq.DATA_CLASS = 'CON_QUOTATION' and pq.enabled_flag = 'Y' ) t1
1=1 and (nvl(t1.due_amount, 0) > nvl(t1.applied_pay_amount,0))
and not exists( select 1 from con_contract_cashflow flow where flow.CASHFLOW_ID = t1.CASHFLOW_ID and flow.CF_ITEM in (60, 67) and nvl(flow.DUE_DATE,flow.fin_income_date) > sysdate)
