SELECT t1.* FROM ( SELECT t.contract_id, t.cashflow_id, cc.contract_number, cc.contract_name, cc.TENANT_ID AS bp_id, cc.contract_status, cc.manufacturer_id, (SELECT m.bp_name FROM hls_bp_master m WHERE cc.factory_id = m.bp_id) AS bp_name_factory, (SELECT m.bp_name FROM hls_bp_master m WHERE cc.manufacturer_id = m.bp_id) AS bp_name_facturer, t.times, t.due_date, t.due_amount, t.cf_item, t.cf_type, t.cf_status, t.cf_direction, i.description AS cf_item_n, ( nvl(t.due_amount, 0) - nvl(t.received_amount, 0) - nvl(t.BLOCK_AMOUNT, 0) - ( select nvl(sum(nvl(dt.DEDUCT_AMOUNT, 0)), 0) from CSH_PAYMENT_REQ_DT dt where dt.SOURCE_DOC_CATEGORY = 'CON_CONTRACT' and dt.SOURCE_DOC_LINE_ID = t.cashflow_id
and not exists( select 1 from CSH_PAYMENT_REQ_LN ln, CSH_PAYMENT_REQ_HD hd where ln.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID and ln.PAYMENT_REQ_ID = hd.PAYMENT_REQ_ID and hd.PAYMENT_REQ_STATUS = 'BACK' ) ) ) AS surplus_amount, ( nvl(t.principal, 0) - nvl(t.received_principal, 0) - nvl(t.BLOCK_PRINCIPAL, 0) - ( select nvl(sum(nvl(dt.DEDUCT_PRINCIPAL, 0)), 0) from CSH_PAYMENT_REQ_DT dt where dt.SOURCE_DOC_CATEGORY = 'CON_CONTRACT' and dt.SOURCE_DOC_LINE_ID = t.cashflow_id
and not exists( select 1 from CSH_PAYMENT_REQ_LN ln, CSH_PAYMENT_REQ_HD hd where ln.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID and ln.PAYMENT_REQ_ID = hd.PAYMENT_REQ_ID and hd.PAYMENT_REQ_STATUS = 'BACK' ) ) ) AS surplus_principal, ( nvl(t.interest, 0) - nvl(t.received_interest, 0) - nvl(t.BLOCK_INTEREST, 0) - ( select nvl(sum(nvl(dt.DEDUCT_INTEREST, 0)), 0) from CSH_PAYMENT_REQ_DT dt where dt.SOURCE_DOC_CATEGORY = 'CON_CONTRACT' and dt.SOURCE_DOC_LINE_ID = t.cashflow_id
and not exists( select 1 from CSH_PAYMENT_REQ_LN ln, CSH_PAYMENT_REQ_HD hd where ln.PAYMENT_REQ_LN_ID = dt.PAYMENT_REQ_LN_ID and ln.PAYMENT_REQ_ID = hd.PAYMENT_REQ_ID and hd.PAYMENT_REQ_STATUS = 'BACK' ) ) ) AS surplus_interest, hbm.BP_NAME, q.quotation_id, q.quotation_number FROM con_contract_cashflow t, prj_quotation q, con_contract cc, hls_cashflow_item i, hls_bp_master hbm WHERE cc.contract_id = t.contract_id AND q.quotation_id = t.generated_source_doc_id AND q.enabled_flag = 'Y' AND i.cf_item = t.cf_item AND cc.TENANT_ID = hbm.BP_ID AND i.cf_type = t.cf_type and t.cf_item in (2,51) ) t1
