#{item}
and ('Y' = #{surplusAmountFlag} and t1.surplus_amount >0)
and t1.cf_item = #{cfItem}
and t1.cf_item != #{nCfItem}
and t1.cf_type = #{cfType}
and t1.cf_type != #{nCfType}
