SELECT bm.BP_NAME,bm.PHONE,c.CONTRACT_NUMBER,due_date,times,due_amount FROM "CON_CONTRACT_CASHFLOW" ccc left join con_contract c ON ccc.CONTRACT_ID = c.CONTRACT_ID LEFT JOIN HLS_BP_MASTER bm ON bm.BP_ID = c.TENANT_ID
trunc(sysdate+#{days}) >= trunc(ccc.due_date) and trunc(ccc.due_date) >= trunc(sysdate) and ccc.cf_item = 1 and ccc.cf_status = 'RELEASE' and ccc.write_off_flag != 'FULL' and ccc.overdue_status ='N'
and c.contract_status =#{contractStatus}
and bm.BP_CLASS =#{bpClass}

SELECT bm.BP_NAME,bm.PHONE,c.CONTRACT_NUMBER,due_date,times,due_amount FROM "CON_CONTRACT_CASHFLOW" ccc left join con_contract c ON ccc.CONTRACT_ID = c.CONTRACT_ID LEFT JOIN HLS_BP_MASTER bm ON bm.BP_ID = c.TENANT_ID
ccc.cf_item = 1 and ccc.cf_status = 'RELEASE' and ccc.write_off_flag != 'FULL' and ccc.overdue_status ='Y'
and c.contract_status =#{contractStatus}
and bm.BP_CLASS =#{bpClass}

select *
from con_contract_cashflow t
where t.CONTRACT_ID = #{contractId}

  and t.GENERATED_SOURCE_DOC_ID = #{quotationId}
  order by t.TIMES asc, t.DUE_DATE asc

select sum(due_amount - nvl(received_amount,0)) amount from con_contract_cashflow where 1=1
and cf_item = #{cfItem}
and generated_source_doc_id = #{generatedSourceDocId}
and generated_source = 'PRJ_QUOTATION' and trunc(due_date) < trunc(sysdate)

select max(cashflow_id) cashflow_id
from con_contract_cashflow
where cf_item = 1
and generated_source = 'PRJ_QUOTATION'

    and due_date < #{dueDate}


    and generated_source_doc_id = #{generatedSourceDocId}

select t1.* from (select ccc.* from con_contract_cashflow ccc where (ccc.cf_item = 1 or ccc.cf_item = 0) and ccc.generated_source = 'PRJ_QUOTATION'
and ccc.due_date < #{dueDate}
and ccc.generated_source_doc_id = #{generatedSourceDocId}
order by ccc.times desc) t1 where rownum = 1

select nvl(sum(ccc.due_amount - nvl(ccc.received_amount,0)), 0) amount, ccc.cf_item from con_contract_cashflow ccc where 1 = 1
and ccc.due_date < #{dueDate, jdbcType=DATE}
and ccc.cf_direction = 'INFLOW' and ccc.generated_source = 'PRJ_QUOTATION'
and ccc.generated_source_doc_id = #{quotationId}
group by ccc.cf_item

select nvl(sum(ccc.principal - nvl(ccc.received_principal,0)),0 ) amount from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.cf_direction = 'INFLOW'
and ccc.due_date >= #{dueDate, jdbcType=DATE}
and ccc.generated_source_doc_id = #{quotationId}

SELECT ccc.* FROM con_contract_cashflow ccc WHERE ccc.contract_id = #{contractId} and ccc.write_off_flag != 'FULL' and ccc.cf_item = 13 AND ccc.cf_status = 'RELEASE' AND ccc.due_date < #{dayEndDate}
union
SELECT ccc.* FROM con_contract_cashflow ccc WHERE ccc.contract_id = #{contractId} and ccc.write_off_flag = 'FULL' and ccc.cf_item = 13 AND ccc.cf_status = 'RELEASE' AND to_char(ccc.FULL_WRITE_OFF_DATE, 'yyyy-MM-dd') = to_char((#{dayEndDate} - interval '1' day), 'yyyy-MM-dd')

select
sum(due_amount - nvl(received_amount,0)) amount
from con_contract_cashflow
where
1=1

    and cf_item = #{cfItem}


    and times > #{times}


    and generated_source_doc_id = #{generatedSourceDocId}

and generated_source = 'PRJ_QUOTATION'

select vv.* from (select cc.contract_number, (select hlc.description from hls_lease_channel hlc where hlc.enabled_flag = 'Y' and hlc.lease_channel = cc.lease_channel) lease_channel_n, (SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'CONTRACT' AND hbt.business_type NOT IN ('CREDIT_LINE') and hbt.business_type = cc.business_type) business_type_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = cc.manufacturer_id) manufacturer_name, (select hbmf.bp_name from hls_bp_master hbmf where hbmf.bp_id = cc.factory_id) factory_bp_name, (select hbmv.bp_name from hls_bp_master hbmv where hbmv.bp_id = cc.bp_id_vender) vender_bp_name, (select hbmt.bp_name from hls_bp_master hbmt where hbmt.bp_id = cc.tenant_id) bp_name, ccc.times,
(select hci.description from hls_cashflow_item hci where hci.cf_item = to_char(ccc.cf_item)) cf_item_n,
ccc.fin_income_date due_date, decode(ccc.cf_item, 1, ccc.due_amount, 11, ccc.due_amount, 13, ccc.due_amount, '') due_amount, decode(ccc.cf_item, 1, ccc.interest, 11, ccc.interest, 13, ccc.interest, '') interest, decode(ccc.cf_item, 1, ccc.principal, 11, ccc.principal, 13, ccc.principal, '') principal, case when ccc.cf_item in (0,1, 11, 13) then nvl((select -1 * nvl(ccc1.due_amount, 0) from con_contract_cashflow ccc1 where ccc1.contract_id = cc.contract_id and ccc1.times = ccc.times and ccc1.cf_item = 60), 0) + nvl((select nvl(ccc2.due_amount, 0) from con_contract_cashflow ccc2 where ccc2.contract_id = cc.contract_id and ccc2.times = ccc.times and ccc2.cf_item = 61), 0) else null end interest_diff, case when ccc.cf_item in (0,1, 11, 13) then nvl((select -1 * nvl(ccc1.due_amount, 0) from con_contract_cashflow ccc1 where ccc1.contract_id = cc.contract_id and ccc1.times = ccc.times and ccc1.cf_item = 67), 0) + nvl((select nvl(ccc2.due_amount, 0) from con_contract_cashflow ccc2 where ccc2.contract_id = cc.contract_id and ccc2.times = ccc.times and ccc2.cf_item = 66), 0) else null end manufacturer_lease_charge, decode(ccc.cf_item, 0, (select cct.due_amount from con_contract_cashflow cct where cct.contract_id = cc.contract_id and cct.cf_item = 65 and cct.times = 0), '') lease_charge, decode(ccc.cf_item, 0,
(select pq.DEPOSIT from PRJ_QUOTATION pq where pq.quotation_id = cc.quotation_id ), '') deposit, ccc.received_amount, ccc.received_principal, ccc.received_interest, nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0) unreceived_amount, nvl(ccc.principal, 0) - nvl(ccc.received_principal, 0) unreceived_principal, nvl(ccc.interest, 0) - nvl(ccc.received_interest, 0) unreceived_interest,
cc.LEASE_START_DATE write_off_date, (select v.meaning from sys_code_value_b_v v where v.code = 'CON.CASHFLOW_WRITE_OFF_FLAG' and v.code_value = ccc.write_off_flag) write_off_flag_n, nvl((select case when to_date(to_char(ccc.due_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') < to_date(to_char(sysdate, 'YYYY-MM-DD'), 'YYYY-MM-DD') and nvl(ccc.due_amount, 0) > nvl(ccc.received_amount, 0) then '是' else '否' end from dual where cc.contract_status != 'SIGN' and cc.contract_status != 'CANCEL'), '否') overdue_status, ccc.outstanding_principal, (select nvl((select to_date(to_char(sysdate, 'YYYY-MM-DD'), 'YYYY-MM-DD') - to_date(to_char(ccc.due_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') from dual where nvl(ccc.due_amount, 0) > nvl(ccc.received_amount, 0) and to_date(to_char(sysdate, 'YYYY-MM-DD'), 'YYYY-MM-DD') > to_date(to_char(ccc.due_date, 'YYYY-MM-DD'), 'YYYY-MM-DD')), (select ceil(ccc.full_write_off_date - ccc.due_date) from dual where nvl(ccc.due_amount, 0) = nvl(ccc.received_amount, 0) and ccc.overdue_status = 'Y')) from dual where cc.contract_status != 'SIGN' and cc.contract_status != 'CANCEL') overdue_days, cc.contract_status, (select scvb.MEANING from SYS_CODE_B scb, SYS_CODE_VALUE_B scvb where scb.code = 'CON.CONTRACT_STATUS' and scb.code_id = scvb.CODE_ID and scvb.value = cc.CONTRACT_STATUS) as contract_status_n, to_char(nvl((select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = ccc.contract_id and cwo.cf_item = 0), (select cash.due_date from con_contract con, con_contract_cashflow cash where con.contract_id = cc.contract_id and con.contract_id = cash.contract_id and cash.times = 0 and cash.cf_item = 0 and con.contract_status in ('INCEPT', 'PENDING', 'TERMINATE'))), 'YYYY/MM/DD') lease_start_date, (select dt.description from hls_document_type dt where dt.document_type = cc.document_type and dt.document_category = cc.document_category) lease_type, cc.vat_rate,cc.contract_id,cc.MANUFACTURER_ID from con_contract_cashflow ccc, con_contract cc where ccc.contract_id = cc.contract_id and ccc.cf_item not in (5,8,9,60,61,65,66,67) and cc.contract_status in('INCEPT','PENDING') and cc.contract_number like '%PRJ%') vv
and exists ( select 1 from sys_user su,hls_bp_master_relation hbmr where su.user_id = #{user_id} and su.bp_id = hbmr.bp_id and hbmr.relation_type = 'MANUFACTURER' and hbmr.related_bp_id = cc.manufacturer_id )
and vv.contract_number like CONCAT(CONCAT('%',#{contractNumber}),'%')
and vv.bp_name like CONCAT(CONCAT('%',#{bpName}),'%')
and vv.lease_channel = #{leaseChannelN}
and vv.business_type = #{business_type_n}
and vv.manufacturer_id = #{manufacturer_bp_name}
and (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = vv.manufacturer_id) = #{manufacturerName}
and vv.factory_id = #{factory_bp_name}
and vv.bp_id_vender = #{bp_id_vender}
and vv.bp_id_tenant = #{bp_id_tenant}
and vv.due_date >= to_date(#{dueDateFrom},'YYYY-MM-DD')
and vv.due_date <= to_date(#{dueDateTo},'YYYY-MM-DD')
and vv.write_off_flag = #{writeOffFlagN}
and nvl(select case when to_date(to_char(vv.due_date, 'YYYY-MM-DD'), 'YYYY-MM-DD') < to_date(to_char(sysdate, 'YYYY-MM-DD'), 'YYYY-MM-DD') and nvl(vv.due_amount, 0) > nvl(vv.received_amount, 0) then '是' else '否' end from dual where vv.contract_status != 'SIGN' and vv.contract_status != 'CANCEL','否') = #{overdue_status}
and vv.vender_mode_flag = #{vender_mode_flag_n}
and vv.cf_item = #{cf_item_n}
and vv.contract_status = #{contractStatus}
and nvl((select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = ccc.contract_id and cwo.cf_item = 0),(select cash.due_date from con_contract con,con_contract_cashflow cash where con.contract_id = cc.contract_id and con.contract_id = cash.contract_id and cash.times = 0 and cash.cf_item = 0 and con.contract_status in ('INCEPT','PENDING','TERMINATE'))) >= to_date(#{leaseStartDateFrom},'YYYY/MM/DD')
and nvl((select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = ccc.contract_id and cwo.cf_item = 0),(select cash.due_date from con_contract con,con_contract_cashflow cash where con.contract_id = cc.contract_id and con.contract_id = cash.contract_id and cash.times = 0 and cash.cf_item = 0 and con.contract_status in ('INCEPT','PENDING','TERMINATE'))) <= to_date(#{leaseStartDateTo},'YYYY/MM/DD')
and (select trunc(max(co.write_off_date)) from con_contract_cashflow t,csh_write_off co where t.times = 0 and t.cf_item = 0 and t.contract_id = vv.contract_id and t.cashflow_id = co.cashflow_id and co.reversed_flag = 'N') >= to_date(#{writeOffDateFrom},'YYYY/MM/DD')
and (select trunc(max(co.write_off_date)) from con_contract_cashflow t,csh_write_off co where t.times = 0 and t.cf_item = 0 and t.contract_id = vv.contract_id and t.cashflow_id = co.cashflow_id and co.reversed_flag = 'N') <= to_date(#{writeOffDateTo},'YYYY/MM/DD')
and vv.times = #{times}
order by vv.contract_id, vv.times

select cc.contract_number, (select hlc.description from hls_lease_channel hlc where hlc.enabled_flag = 'Y' and hlc.lease_channel = cc.lease_channel) lease_channel_n, (SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'CONTRACT' AND hbt.business_type NOT IN ('CREDIT_LINE') and hbt.business_type = cc.business_type) business_type_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = cc.manufacturer_id) manufacturer_bp_name, (select hbmf.bp_name from hls_bp_master hbmf where hbmf.bp_id = cc.factory_id) factory_bp_name, (select hbmv.bp_name from hls_bp_master hbmv where hbmv.bp_id = cc.bp_id_vender) vender_bp_name, (select hbmt.bp_name from hls_bp_master hbmt where hbmt.bp_id = cc.tenant_id) tenant_bp_name,
ccc.times, (select hci.description from hls_cashflow_item hci where hci.cf_item = to_char(ccc.cf_item)) cf_item_n, ccc.fin_income_date due_date_n,
ccc.due_amount, ccc.principal, ccc.interest, ccc.received_amount, ccc.received_principal, ccc.received_interest, nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0) unreceived_amount, nvl(ccc.principal, 0) - nvl(ccc.received_principal, 0) unreceived_principal, nvl(ccc.interest, 0) - nvl(ccc.received_interest, 0) unreceived_interest, (select max(cwo.write_off_date) from csh_write_off cwo where cwo.cashflow_id = ccc.cashflow_id) write_off_date, (select v.meaning from sys_code_value_b_v v where v.code = 'CON.CASHFLOW_WRITE_OFF_FLAG' and v.code_value = ccc.write_off_flag) write_off_flag_n,
ccc.outstanding_principal,
(select scvb.MEANING from SYS_CODE_B scb, SYS_CODE_VALUE_B scvb where scb.code = 'CON.CONTRACT_STATUS' and scb.code_id = scvb.CODE_ID and scvb.value = cc.CONTRACT_STATUS) as contract_status_n, cc.LEASE_START_DATE,
case when ccc.cf_item = 9 then case when (select count(1) from con_contract_cashflow t where t.contract_id = ccc.contract_id and t.cf_item in (11, 13)) > 0 then (select to_char(max(t.due_date), 'YYYY-MM-DD') from con_contract_cashflow t where t.contract_id = ccc.contract_id and t.cf_item in (11, 13)) else (select to_char(max(t.due_date), 'YYYY-MM-DD') from con_contract_cashflow t where t.contract_id = ccc.contract_id and t.cf_item = 1) end when ccc.cf_item = 99 then (select to_char(cash.due_date, 'YYYY-MM-DD') from con_contract_cashflow cash where cash.contract_id = ccc.contract_id and cash.times = ccc.times and cash.cf_item = 13) else to_char(ccc.due_date, 'YYYY-MM-DD') end due_date_new, (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value=ccc.overdue_status) overdue_status,
(select sum(to_date(sysdate) - to_date(cccc.due_date)) from con_contract_cashflow cccc where cccc.contract_id = cc.contract_id and cccc.cf_status = 'RELEASE' and ccc.cf_direction = 'INFLOW' and ccc.overdue_status = 'Y' ) overdue_days,
(select v.meaning from sys_code_value_b_v v where v.code='EXEMPT_PENALTY_INT' and v.code_value=(select hpd.exempt_penalty_int from hls_product_definition hpd,prj_quotation pq where hpd.definition_id=pq.plan_id and pq.quotation_id=cc.quotation_id)) grace_flag_n, (select hpdd.default_value from HLS_PRODUCT_DEFINITION_PARA hpdd,prj_quotation pq where hpdd.definition_id=pq.plan_id and pq.quotation_id=cc.quotation_id and hpdd.product_para='GRACE_PERIOD') grace_period ,cc.CONTRACT_STATUS from con_contract_cashflow ccc, con_contract cc, HLS_BP_MASTER m1 where ccc.contract_id = cc.contract_id and cc.TENANT_ID = m1.BP_ID and cc.contract_number like '%PRJ%' and cc.CONTRACT_STATUS in ('INCEPT','PENDING')
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a4.position_id=a3.position_id and employee_code=#{request.employeeCode} AND A4.position_id IN(select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND (a.user_id =cc.created_by or a.user_id=m1.created_by) )) )
and exists (select 1 from sys_user su, hls_bp_master_role hbmr where su.bp_id = hbmr.bp_id and (su.user_id = #{user_id} or su.user_id in (select su1.user_id from sys_user su1,sys_user su2,hls_bp_master_relation hmr1 where su2.user_id = #{user_id} and su1.bp_id = hmr1.bp_id and hmr1.relation_type = 'PARENT_COMPANY' and hmr1.related_bp_id = su2.bp_id) or su.user_id in (select su1.user_id from sys_user su1,sys_user su2,hls_bp_master_relation hmr1 where su2.user_id = #{user_id} and su1.bp_id = hmr1.related_bp_id and hmr1.relation_type = 'SUBSIDIARY' and hmr1.bp_id = su2.bp_id)) and (exists (select 1 from hls_bp_master_relation rel where hbmr.bp_category = 'MANAGEMENT_COMPANY' and rel.bp_id = su.bp_id and rel.relation_type = 'MANUFACTURER' and cc.manufacturer_id = rel.related_bp_id) or exists (select 1 from dual where hbmr.bp_category = 'MANUFACTURER' and cc.manufacturer_id = su.bp_id) or exists (select 1 from dual where hbmr.bp_category = 'VENDER' and cc.factory_id = su.bp_id) or exists (select 1 from dual where hbmr.bp_category = 'DEALER' and cc.bp_id_vender = su.bp_id))) And ((nvl((Select decode((Select Count(*) From hls_bp_master_role hr Where hr.bp_id = su.bp_id And hr.bp_type In ('DEALER', 'DISTRIBUTOR')), 0, 'TENANT', 'DEALER') bp_category From sys_user su Where su.user_id = #{user_id}), 'ADMIN') In ('DEALER', 'DISTRIBUTOR') And ccc.cf_item Not In (60, 61, 66, 67)) Or (nvl((Select decode((Select Count(*) From hls_bp_master_role hr Where hr.bp_id = su.bp_id And hr.bp_type In ('DEALER', 'DISTRIBUTOR')), 0, 'TENANT', 'DEALER') bp_category From sys_user su Where su.user_id = #{user_id}), 'ADMIN') Not In ('DEALER', 'DISTRIBUTOR')))
and cc.contract_number like CONCAT(CONCAT('%',#{contractNumber}),'%')
and cc.lease_channel = #{leaseChannelN}
and cc.business_type = #{businessTypeN}
and cc.manufacturer_id = #{manufacturerBpName}
and cc.factory_id = #{factoryBpName}
and cc.bp_id_vender = #{bpIdVender}
and cc.tenant_id = #{bpIdTenant}
and trunc(case when ccc.cf_item = 9 then (select cash.due_date from con_contract_cashflow cash where cash.contract_id = ccc.contract_id and cash.times = ccc.times and cash.cf_item = 1) when ccc.cf_item = 99 then (select cash.due_date from con_contract_cashflow cash where cash.contract_id = ccc.contract_id and cash.times = ccc.times and cash.cf_item = 13) else ccc.due_date end) >= to_date(#{dueDateFrom},'YYYY-MM-DD')
and trunc(case when ccc.cf_item = 9 then (select cash.due_date from con_contract_cashflow cash where cash.contract_id = ccc.contract_id and cash.times = ccc.times and cash.cf_item = 1) when ccc.cf_item = 99 then (select cash.due_date from con_contract_cashflow cash where cash.contract_id = ccc.contract_id and cash.times = ccc.times and cash.cf_item = 13) else ccc.due_date end) <= to_date(#{dueDateTo},'YYYY-MM-DD')
and ccc.write_off_flag = #{writeOffFlagN}
and ccc.overdue_status = #{overdueStatus}
and cc.vender_mode_flag = #{vender_mode_flag_n}
and ccc.cf_item = #{cfItemN}
and cc.contract_status = #{contractStatus}
and nvl((select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = ccc.contract_id and cwo.cf_item = 0),(select cash.due_date from con_contract con,con_contract_cashflow cash where con.contract_id = cc.contract_id and con.contract_id = cash.contract_id and cash.times = 0 and cash.cf_item = 0 and con.contract_status in ('INCEPT','PENDING','TERMINATE'))) >= to_date(#{leaseStartDateFrom},'YYYY/MM/DD')
and nvl((select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = ccc.contract_id and cwo.cf_item = 0),(select cash.due_date from con_contract con,con_contract_cashflow cash where con.contract_id = cc.contract_id and con.contract_id = cash.contract_id and cash.times = 0 and cash.cf_item = 0 and con.contract_status in ('INCEPT','PENDING','TERMINATE'))) <= to_date(#{leaseStartDateTo},'YYYY/MM/DD')
and ( SELECT hbmv.bp_name FROM hls_bp_master hbmv WHERE hbmv.bp_id = cc.bp_id_vender ) like #{vender_bp_name}
order by ccc.contract_id, ccc.times

select ccc.* (ccc.due_amount - nvl(ccc.received_amount, 0)) surplus_amount, (ccc.principal - nvl(ccc.received_principal, 0)) end surplus_principal, (ccc.interest - nvl(ccc.received_interest, 0)) surplus_interest from con_contract_cashflow ccc, con_contract cc where ccc.contract_id = #{contractId} and ccc.cf_type in (1, 8, 9) and ccc.cf_item in (1, 8, 9, 11, 13) and ccc.write_off_flag != 'FULL' and cc.contract_id = ccc.contract_id
and #{queryTimes} = #{queryTimes}
order by case when ccc.cf_item = 9 then 1 when ccc.cf_item = 1 then 2 when ccc.cf_item = 11 then 3 when ccc.cf_item = 13 then 4 when ccc.cf_item = 8 then 5 end asc, ccc.due_date desc, ccc.times desc

mapper.update:
update con_contract_cashflow ccc
set ccc.received_amount = #{receivedAmount}, ccc.write_off_flag =#{writeOffFlag}
where ccc.contract_id = #{contractId}
  and ccc.cf_item = 0
